WITH gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM transactions) SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, SUM(new_group_flag) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps;
